inline_styles:
/* Purnabakti Detail Styles */
.mpp-detail-hero {
  background: linear-gradient(135deg, #091e36 0%, #102d4f 50%, #0d2238 100%);
  color: #fff;
  padding: 50px 0 44px;
  border-bottom: 4px solid #f59e0b;
}
.mpp-detail-hero .badge {
  display: inline-block;
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fde68a;
  font-size: 12.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 5px 12px;
  border-radius: 6px;
  margin-bottom: 14px;
}
.mpp-detail-hero h1 {
  font-size: clamp(24px, 3.6vw, 38px);
  font-weight: 800;
  line-height: 1.25;
  color: #fff;
  margin: 0 0 16px;
}
.mpp-detail-hero p.tagline {
  font-size: clamp(15px, 1.8vw, 17px);
  color: #e2e8f0;
  max-width: 820px;
  line-height: 1.6;
  margin-bottom: 24px;
}
.mpp-meta-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 18px 22px;
  margin-bottom: 24px;
}
.mpp-meta-item {
  flex: 1;
  min-width: 200px;
}
.mpp-meta-item span.lbl {
  display: block;
  font-size: 11.5px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin-bottom: 4px;
}
.mpp-meta-item strong {
  font-size: 15px;
  color: #fff;
  font-weight: 700;
}
.mpp-meta-item strong.price {
  color: #34d399;
  font-size: 17px;
}

/* Content Layout */
.mpp-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 40px;
  padding: 48px 0 60px;
}
@media (max-width: 991px) {
  .mpp-layout {
    grid-template-columns: 1fr;
  }
}

.mpp-body {
  font-size: 15.5px;
  line-height: 1.8;
  color: #334155;
}
.mpp-body h2 {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  margin: 36px 0 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid #e2e8f0;
}
.mpp-body h3 {
  font-size: 19px;
  font-weight: 800;
  color: #0f172a;
  margin: 28px 0 12px;
}
.mpp-body p {
  margin-bottom: 18px;
  white-space: pre-line;
}

/* Table Styles */
.mpp-syllabus-table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0 32px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;
  font-size: 14px;
}
.mpp-syllabus-table th {
  background: #091e36;
  color: #fff;
  padding: 12px 16px;
  text-align: left;
  font-weight: 700;
  font-size: 13px;
}
.mpp-syllabus-table td {
  padding: 14px 16px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: top;
  color: #334155;
}
.mpp-syllabus-table tr:hover td {
  background: #f8fafc;
}

/* Itinerary List */
.mpp-rundown-box {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 24px;
  margin: 24px 0 32px;
}
.mpp-rundown-item {
  display: flex;
  gap: 16px;
  margin-bottom: 18px;
  padding-bottom: 18px;
  border-bottom: 1px dashed #cbd5e1;
}
.mpp-rundown-item:last-child {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.mpp-day-badge {
  background: #091e36;
  color: #fde68a;
  font-weight: 800;
  font-size: 13px;
  padding: 6px 12px;
  border-radius: 8px;
  height: fit-content;
  white-space: nowrap;
}
.mpp-rundown-content h4 {
  margin: 0 0 6px;
  font-size: 15.5px;
  color: #0f172a;
}
.mpp-rundown-content p {
  margin: 0;
  font-size: 14px;
  color: #475569;
  line-height: 1.6;
}

/* Sidebar Widgets */
.mpp-sidebar-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 24px;
  margin-bottom: 24px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.03);
}
.mpp-sidebar-card h3 {
  font-size: 17.5px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 14px;
}
.mpp-sidebar-card p {
  font-size: 13.5px;
  color: #64748b;
  line-height: 1.6;
  margin-bottom: 16px;
}
.mpp-sidebar-price {
  background: #f8fafc;
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 18px;
  border: 1px solid #e2e8f0;
}
.mpp-sidebar-price .lbl {
  font-size: 12px;
  color: #64748b;
  text-transform: uppercase;
}
.mpp-sidebar-price .val {
  font-size: 20px;
  font-weight: 800;
  color: #0A4A2E;
  margin: 4px 0 0;
}
.mpp-btn-full-wa {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: #25D366;
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  padding: 12px 18px;
  border-radius: 10px;
  text-decoration: none;
  width: 100%;
  box-sizing: border-box;
  transition: all .2s;
}
.mpp-btn-full-wa:hover {
  background: #20ba5a;
  color: #fff;
}
.mpp-b2b-badge-box {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  border-radius: 10px;
  padding: 14px;
  font-size: 13px;
  color: #1e40af;
  margin-top: 16px;
  line-height: 1.5;
}
